<?php defined('VV_ROOT') || exit; ?>
<section class="vv-form" id="form-<?=e($id)?>" aria-labelledby="form-<?=e($id)?>-title"><h2 id="form-<?=e($id)?>-title"><?=e($f['name'])?></h2>
<?php if($success):?><p class="vv-form-success" role="status"><?=e($f['confirmation'])?></p><?php endif;?>
<?php if($errors):?><div class="vv-form-error" role="alert"><?=e(t('Vérifiez les champs ci-dessous.','Check the fields below.'))?> <?=e($errors['_form']??'')?></div><?php endif;?>
<form method="post" action="<?=e(\VV\Content::url($c).'#form-'.$id)?>"><input type="hidden" name="cms_action" value="forms.submit"><input type="hidden" name="form_id" value="<?=e($id)?>"><input type="hidden" name="content_id" value="<?=e($c['id'])?>"><input type="hidden" name="forms_token" value="<?=e(self::$token)?>"><input type="hidden" name="submission" value="<?=e($nonce)?>">
<p class="vv-privacy"><?=nl2br(e($f['privacy']))?> <?=e(t('Conservation :','Retention:'))?> <?=$f['retention_days']?> <?=e(t('jours.','days.'))?></p>
<?php foreach($f['fields'] as $field):$key=$field['key'];$hid='form-'.$id.'-'.$key;$value=$values[$key]??'';?><fieldset>
<?php if($field['type']==='checkbox'):?><label class="vv-check" for="<?=e($hid)?>"><input type="checkbox" id="<?=e($hid)?>" name="fields[<?=e($key)?>]" value="yes" <?=$value==='yes'?'checked':''?> <?=$field['required']?'required':''?> aria-describedby="<?=e($hid.'-help '.$hid.'-error')?>"><span><?=e($field['label'])?><?=$field['required']?' *':''?></span></label>
<?php else:?><label for="<?=e($hid)?>"><?=e($field['label'])?><?=$field['required']?' *':''?></label>
<?php if($field['type']==='textarea'):?><textarea id="<?=e($hid)?>" name="fields[<?=e($key)?>]" maxlength="2000" rows="5" <?=$field['required']?'required':''?> aria-describedby="<?=e($hid.'-help '.$hid.'-error')?>" <?=isset($errors[$key])?'aria-invalid="true"':''?>><?=e($value)?></textarea>
<?php elseif($field['type']==='select'):?><select id="<?=e($hid)?>" name="fields[<?=e($key)?>]" <?=$field['required']?'required':''?> aria-describedby="<?=e($hid.'-help '.$hid.'-error')?>"><option value=""><?=e(t('Choisir…','Choose…'))?></option><?php foreach($field['choices'] as $choice):?><option value="<?=e($choice)?>" <?=$choice===$value?'selected':''?>><?=e($choice)?></option><?php endforeach;?></select>
<?php else:?><input type="<?=e($field['type'])?>" id="<?=e($hid)?>" name="fields[<?=e($key)?>]" value="<?=e($value)?>" maxlength="<?=$field['type']==='email'?254:200?>" <?=$field['required']?'required':''?> aria-describedby="<?=e($hid.'-help '.$hid.'-error')?>" <?=isset($errors[$key])?'aria-invalid="true"':''?>><?php endif;?><?php endif;?>
<small id="<?=e($hid)?>-help"><?=e($field['help'])?></small><small class="vv-form-error" id="<?=e($hid)?>-error"><?=e($errors[$key]??'')?></small></fieldset><?php endforeach;?>
<div class="vv-form-honey" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button type="submit"><?=e(t('Envoyer la demande','Send request'))?></button></form></section>
